from pathlib import Path
import base64, io, zipfile, sys

PAYLOAD = """"""

def main():
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python3 apply_v09_patch.py <extracted-v08-project-dir>")
    root = Path(sys.argv[1]).resolve()
    if not (root / "app" / "build.gradle.kts").exists():
        raise SystemExit(f"Target does not look like AB Khatma project: {root}")
    data = base64.b64decode(PAYLOAD)
    with zipfile.ZipFile(io.BytesIO(data)) as z:
        z.extractall(root)
    print("Applied AB Khatma V0.9 Quran/Husary/meanings safe patch to", root)

if __name__ == "__main__":
    main()
